// defs.schema.json

/** Identifier for course elements (screens, blocks, layers, free objects, events). Lowercase letters, digits and hyphens, starting with a letter. Must be unique in the whole course. Ids are permanent: learner progress is keyed by id, so rename one only with elabora rename, which rewrites every reference and keeps its key in elabora.lock.json. */
export type Slug = string;

/** Identifier of a plan element (objective, item, locked text, question, source). Uppercase letters, digits, hyphens or underscores, for example OBJ-2, ITEM-5, TXT-3, Q-12, SRC-1. */
export type PlanId = string;

/** Variable identifier: starts with a lowercase letter, then letters, digits or underscores (camelCase or snake_case). */
export type VariableId = string;

/** Semantic version, for example 1.0.0. */
export type Semver = string;

/** Text in the Elabora Markdown subset: paragraphs, **bold**, *italic*, lists, tables, links, `code`, line breaks, and maths in LaTeX between $…$ (inline) or $$…$$ (display), rendered as MathML at build time. Raw HTML is not rendered. Images must use image blocks, not Markdown. */
export type Markdown = string;

/** One operation of a JSON Patch (RFC 6902), as elabora plan write --patch and MCP elabora_write_plan take it. */
export type PatchOperation = {
  op: 'add' | 'remove' | 'replace' | 'move' | 'copy' | 'test';
  path: string;
  from?: string;
  value?: unknown;
};

/** Path of a file inside the course assets/ folder, relative to assets/ (for example images/router.png). ASCII letters, digits, '-', '_', '.', '/' only, so every LMS accepts the file name. */
export type AssetPath = string;

/** Colour as a 6-digit hex value, for example #12355B. */
export type Color = string;

/** Words a generated voice says otherwise than they are written, by language tag: each text (a whole word or phrase, case-sensitive) is said as say. Captions and the transcript keep the text. */
export type Pronunciations = { [key: string]: Pronunciation[] };

export type Pronunciation = {
  /** As written in the lines (P-12, 9 h 30). */
  text: string;
  /** As the voice should say it (pé douze, neuf heures trente). */
  say: string;
};

/** A moment of the screen's timeline, written against what the voice says rather than in seconds, so that it holds when a voice is generated again, recorded or translated: a line ({ "line": "l2" }), a word or a few words of it ({ "line": "l2", "word": "imprimante" }), the end of either (edge end), shifted by offset seconds. On a screen without narration, seconds from the start of a step ({ "seconds": 1.5 }). The start or the end of a step's stretch of the timeline ({ "step": 2 }, { "step": 2, "edge": "end" }). */
export type Anchor = {
  /** A line of the screen's narration (narration.lines[].id). */
  line?: Slug;
  /** One or a few words of the line, as written there (case, punctuation and apostrophes aside): the moment the voice says them. Their time comes from the line's word times (the sidecar's words, filled by forced alignment), estimated from the text without them. Translations carry it as a marker that translators place on the words of their language. A word no longer in the line is an error (E_TIMELINE_ANCHOR_MISSING); editing the line's text moves the anchor with its word. */
  word?: string;
  /**
   * Which time the word appears in the line, when it appears more than once.
   * @default 1
   */
  occurrence?: number;
  /**
   * start: when the line, the word or the step starts. end: when it ends.
   * @default 'start'
   */
  edge?: 'start' | 'end';
  /** Seconds after the line or the word (negative: before). */
  offset?: number;
  /** Screens without narration only: seconds from the start of a step (step, else the block's step, else 1). Narrated screens anchor to their lines and words. */
  seconds?: number;
  /** With seconds: the step they count from. Alone: the start of that step's stretch of the timeline, or its end with edge end. */
  step?: number;
};

/** When a timed block appears (timing.in) or leaves (timing.out), and how. */
export type Moment = {
  at: Anchor;
  /** How it comes or goes: none (at once), fade, rise (moves up a few pixels while fading in), slide (from direction), zoom, wipe (uncovered from direction), draw (the strokes of its drawing are drawn; a wipe for blocks without one), or an effect of the course's theme (course.json theme.effects). Effects move the block relative to its place, never the layout. Default: fade (the transition of a pile for its contents). Under reduced motion every effect becomes a short fade, at the same times. */
  effect?: string;
  /** Seconds the effect lasts. Default: 0.4 (fade, zoom), 0.5 (rise, slide), 0.6 (wipe), 1.2 (draw), 0.4 for theme effects. */
  duration?: number;
  /** slide and wipe: where the block comes from (default left: it slides in from the left, or is uncovered from left to right). */
  direction?: 'left' | 'right' | 'up' | 'down';
};

/** BCP 47 language tag, for example fr, en, fr-FR. */
export type Language = string;

/** Calendar date, YYYY-MM-DD. */
export type CalendarDate = string;

/** Accepted distance from the expected value: absolute (same unit as the answer) or percent of the answer. Without tolerance only the exact value is accepted. */
export type NumericTolerance = {
  /** Accept answer ± this value. */
  absolute?: number;
  /** Accept answer ± this percentage of the answer. */
  percent?: number;
};

/** Elaborated feedback of a numeric question (guardrail D1): why the expected value is right, and what to check when the answer is wrong. */
export type NumericFeedback = {
  correct: Markdown;
  /** Shown for wrong values that match no misconception. */
  incorrect: Markdown;
};

/** Values learners get with a typical error, each with feedback that names the error. They are checked before the generic incorrect feedback. */
export type Misconceptions = Misconception[];

export type Misconception = {
  id: string;
  value: number;
  tolerance?: NumericTolerance;
  feedback: Markdown;
};

/** Shape of an embedded frame. auto: the free object sets its own height (host.requestHeight). fill: the frame fills the height of its layout slot. */
export type AspectRatio = '16:9' | '21:9' | '3:2' | '4:3' | '1:1' | '3:4' | '2:3' | '9:16' | 'auto' | 'fill';

/** Preset of the media shipped in a package: high (the masters), medium or low (renditions encoded from the masters, for LMS size limits). */
export type MediaQuality = 'high' | 'medium' | 'low';

// course.schema.json

/**
 * Elabora course (course.json)
 *
 * Root file of an Elabora course project. It lists the sections and the order of screens, declares variables, the theme, navigation, completion and tracking rules. Screens live in screens/<id>.json, the validated plan in plan.json.
 */
export type Course = {
  $schema?: string;
  /** Format identifier and version. Always "elabora/0.1" for this version of the specification. Older courses are migrated by elabora migrate (Elabora reads them migrated in memory meanwhile). */
  format: 'elabora/0.1';
  /** Stable course identifier. Used for the SCORM manifest identifiers: changing it makes LMSs treat the package as a different course. */
  id: Slug;
  /** Course title shown to learners and in the LMS. */
  title: string;
  /** Short description for the LMS catalogue. */
  description?: string;
  /** Language of the content. Selects the player labels (fr and en are built in). */
  language: Language;
  /** Content version of the course. Increase it at every delivery. */
  version: Semver;
  /** Typical learner duration, written into the SCORM manifest metadata. */
  durationMinutes?: number;
  /** Ordered sections (modules) of the course. Each lists the ids of its screens, in learner order. Every screen must appear exactly once. */
  sections: CourseSection[];
  /** Course variables, readable and writable by events. Persisted variables are saved in the learner's suspend data, so their size counts against the LMS budget. */
  variables?: Variable[];
  /** The voices of the course's narration (screen narration lines name them): the name shown in captions and in the transcript, and the voice that speaks each language. */
  speakers?: Speaker[];
  /** Defaults of the course's narrated screens (each screen's narration may say otherwise). */
  narration?: {
    /**
     * How narrated screens advance (screen narration.advance).
     * @default 'learner'
     */
    advance?: 'learner' | 'auto' | 'next-screen';
    /**
     * How far learners may move in their timeline (screen narration.seek): seen, back anywhere and forward up to the furthest point reached; free, anywhere. Whether the seek bar shows at all is the player's (player controls option seekBar); a screen may still hide its own (screen narration.seek none).
     * @default 'seen'
     */
    seek?: 'seen' | 'free';
  };
  /** The learner's player around the screens (docs/decisions.md D58): two bars, top and bottom, each an ordered list of items. An item shows when it is enabled and has something to show (resources, glossary, credits and the logo need their content; exit shows in SCORM packages only); a bar with nothing to show is removed and the screen takes its room. A bar left out (or without its own items) takes its default items, less those placed in the other bar; an item left out of both bars is not shown. Each item may be in one bar only (the spacer once in each bar). Its colours and size come from the theme's player.* tokens. */
  player?: {
    /** The bar above the screen. Default: logo (disabled), title, progress, spacer, resources, glossary, credits, exit. */
    top?: PlayerBar;
    /** The bar below the screen. Default: outline, controls, spacer, previous, next. */
    bottom?: PlayerBar;
  };
  /** What learners may open or download from the player's Resources: files of assets/ shipped in the package (a job aid, a checklist, a form), and links (a page of the intranet). A PDF or an image opens in a preview over the module with « Télécharger »; any other file downloads; a link opens in a new tab. Shown by the player item resources. */
  resources?: {
    id: Slug;
    /** What learners read in the list (« Fiche réflexe : incident réseau »). */
    title: string;
    /** One line on what the file is for, under its title. */
    description?: string;
    /** The file, relative to assets/ (resources/fiche-reflexe.pdf). PDF, office documents, text, images, audio, video or ZIP: formats every LMS web server serves (W_RESOURCE_TYPE otherwise). A resource has an asset or a url. */
    asset?: AssetPath;
    /** A link instead of a file, opened in a new tab: an https:// address (E_RESOURCE_URL otherwise). */
    url?: string;
  }[];
  /** The course's glossary: the terms learners may look up from the player's Glossary (a panel with search, entries in alphabetical order). A text links a word to its entry with a Markdown link to glossary:<id> ([passerelle](glossary:gateway)): the player shows the definition when it is hovered or focused, and the link opens the Glossary there. Translated with the course. */
  glossary?: CourseGlossary[];
  /** The author's credits, one line each (« Conception pédagogique : Claire Martin », « Photographies : … https://… »): shown in the player's « IA et crédits » after what the course says by itself (its AI-generated voices and media, its voices' attributions). Addresses become links. Translated with the course. */
  credits?: string[];
  /** How generated voices say words of the whole course (an acronym, a reference, a name), by language: each language has its own list, never translated. */
  pronunciations?: Pronunciations;
  /** Warnings the author looked at and chose to ignore (docs/decisions.md D31): the validator marks the finding of that code with that key ignored, and it counts no more. A key names what the finding is about and a fingerprint of what was found (a swallowed word: the line, the word and its take's audio), so a finding that changes (another take) comes back. Written by the editor (ignore_findings), not by update_course; unlike plan waivers, nobody approves them, and the proof dossier says them ignored by the author. Never shipped in packages. */
  ignored?: CourseIgnored[];
  theme?: Theme;
  /** How screens are presented. scroll: a document per screen (default); steps appear one below the other. slides: every screen is one view that should fit the window (checked by elabora fit and elabora test at the fit sizes); steps appear in their reserved place. Sizes are in px at the reference window (1600×900) and follow the size classes of the player (1rem is 14 px at 1280×720). */
  presentation?: {
    /** @default 'scroll' */
    mode?: 'scroll' | 'slides';
    /**
     * Width of the reading column (blocks of width full), in px at the reference window; emitted in rem, so it follows the size classes.
     * @default 760
     */
    contentWidth?: number;
    /**
     * Width of wide blocks and of the screen, in px at the reference window; emitted in rem.
     * @default 1100
     */
    wideWidth?: number;
    /** Window sizes (width x height, CSS px, inside the LMS frame) where a slide must fit without scrolling. reference: the size the course is designed for; an overflow there is a warning (W_SLIDE_OVERFLOW). minimum: the smallest supported size; slides may scroll there and an overflow is only reported (I_SLIDE_OVERFLOW_MINIMUM). Below it, and on phones, slides read as a scrolling page. */
    fit?: {
      /** @default '1600x900' */
      reference?: string;
      /** @default '1280x720' */
      minimum?: string;
    };
  };
  /** Player navigation rules: where learners may go. What the player shows (the outline, the progress, Previous and Next) is course.json player (D58). */
  navigation?: {
    /**
     * linear: learners go on with Next, and the outline opens the screens already reached. free: learners can also jump to any screen from the outline.
     * @default 'linear'
     */
    mode?: 'linear' | 'free';
    /**
     * If true, Next refuses to go on (a tooltip says why) until the current screen is complete.
     * @default false
     */
    lockUntilComplete?: boolean;
  };
  /** How the course reports completion and success to the LMS. The final status is sent once, when it is decided (never only at exit). */
  completion?: {
    /**
     * Status pair reported in SCORM 1.2 cmi.core.lesson_status, as in Storyline. completed-incomplete: completed when all required screens are complete. passed-incomplete: passed when required screens are complete and the score reaches masteryScore. passed-failed: passed or failed once every scored item is answered. completed-failed: completed when required screens are complete, failed if the score is below masteryScore.
     * @default 'completed-incomplete'
     */
    reportAs?: 'completed-incomplete' | 'passed-incomplete' | 'passed-failed' | 'completed-failed';
    /** Passing score in percent. Required for every reportAs except completed-incomplete. Written to the manifest as adlcp:masteryscore. */
    masteryScore?: number;
  };
  /** Tracking behaviour. */
  tracking?: {
    /**
     * Value of cmi.core.exit once the course is complete. suspend keeps resume data for review; normal ends the attempt. Never logout (SuccessFactors logs the learner out).
     * @default 'suspend'
     */
    exitAfterCompletion?: 'suspend' | 'normal';
    /**
     * Write quiz, decision and free-object answers to cmi.interactions, linked to plan objectives.
     * @default true
     */
    recordInteractions?: boolean;
    /**
     * Periodic commit of session time while the course is open (0 disables). Keeps long sessions alive in LMSs that expire them.
     * @default 60
     */
    heartbeatSeconds?: number;
  };
  /** How the SCORM package is delivered. */
  delivery?: {
    /**
     * Preset of the video, audio and raster images shipped in the package (elabora build --media-quality overrides it for one build). high: the masters the project keeps (video H.264 long side ≤ 1920, CRF 21, ≤ 8 Mb/s, AAC 160 kb/s; audio AAC 160 kb/s; images long side ≤ 3200, WebP q 88). medium: renditions encoded from the masters (video ≤ 1280, CRF 24, ≤ 4 Mb/s, AAC 128 kb/s; audio AAC 128 kb/s; images ≤ 2400, q 80). low: smaller renditions for LMSs with tight size limits (video ≤ 854, CRF 27, ≤ 1.5 Mb/s, ≤ 30 fps, AAC 96 kb/s; audio AAC 96 kb/s; images ≤ 1600, q 72). A rendition that would be larger than its master ships the master; SVG images are never re-encoded. E_PACKAGE_TOO_LARGE says what the lower presets would weigh.
     * @default 'high'
     */
    mediaQuality?: MediaQuality;
    /** The LMS the course is delivered to: ids of LMS profiles (elabora profiles lists them). elabora build, validate and test target them when no --profile is given: the package must fit their limits (size, files, suspend data). Without it the course targets an unknown LMS: the strictest documented behaviour, and package limits only warn, naming the LMSs that would refuse the package. */
    lms?: string[];
  };
  /** Overrides for player labels, keyed by label id (see docs). Example: {"next": "Continuer"}. */
  ui?: { [key: string]: string };
  /** Set by elabora translate build: this course is the translation of another (its id, version and language). Generated: edit the source course and its translations/<lang>.xlf. */
  translationOf?: {
    id: string;
    version: string;
    language: string;
  };
};

export type CourseSection = {
  id: Slug;
  title: string;
  screens: Slug[];
};

export type CourseGlossary = {
  /** Named by glossary:<id> links. */
  id: Slug;
  term: string;
  /** One to three sentences, plain text. */
  definition: string;
  /**
   * false: « Le terme ne se traduit pas »: the term and its variants are not sent for translation and stay as they are in every language (a product name, a procedure code); the definition still is translated.
   * @default true
   */
  translate?: boolean;
  /** Other forms and synonyms learners may search for (plural, acronym, spelled out): « VPN », « réseau privé virtuel ». */
  variants?: string[];
  /** Where the term was found when it was gathered (« Relever les termes »): a source of the author's sources/ (D49) or a screen of the course. For the author and the editor, which shows it beside the entry: never shown to learners, never translated, left out of packages. */
  source?: {
    /** source: a file of sources/; screen: a screen of the course. */
    kind: 'source' | 'screen';
    /** The source's name in sources/ (« brief-client.pdf »), or the screen's id. */
    id: string;
    /** Where in it, as the author would find it: « p. 4 », « diapositive 12 », « 02:15 ». */
    at?: string;
  };
};

export type CourseIgnored = {
  /** The code of the finding ignored: a warning or an information, never an error. */
  code: string;
  /** The finding's key (Diagnostic.key): what it is about, then @ and the fingerprint of what was found. */
  key: string;
};

export type PlayerBar = {
  /** The items of the bar, in order from the start of the line (left in left-to-right languages). With a spacer, what is before it goes to the start of the line and what is after it to the end. Without one, the room left goes to the title or the controls, else before the first of resources, glossary, language, display, credits, exit, previous and next that follows another item. */
  items?: PlayerItem[];
  /**
   * window: the bar stays in the window (at its top or its bottom) while the page scrolls. page: the top bar scrolls away with the page; the bottom bar comes at the end of the page, after its content and once its last step is shown, like the end of a lesson in Rise (scroll presentation; the controls of a narrated screen stay in the window). In slides the page ends with the window: both look alike.
   * @default 'window'
   */
  position?: 'window' | 'page';
};

export type PlayerItem = {
  /** logo: the course's logo image. title: the course title. progress: the share of required screens completed. spacer: « Espace flexible », what is before it goes to the start of the line and what is after it to the end (the controls stretch first, the spacer takes what remains); one in each bar, always on. outline: the drop-down table of contents (sections and screens, what is done, what is not open yet). controls: the controls of narrated screens (play, replay, seek bar, time, captions, settings, volume, transcript). resources: the course's resources. glossary: the course's glossary. language: « Langue », the languages the package holds, to switch in place (shown when it holds more than one: elabora build --languages all). display: « Affichage », the learner's text size, larger captions and the keyboard shortcuts. credits: « IA et crédits », what was made with AI and the credits. previous, next: the navigation buttons; unavailable, they stay in place, greyed. exit: « Quitter », saves and ends the session (D3; SCORM packages only). */
  id: 'logo' | 'title' | 'progress' | 'spacer' | 'outline' | 'controls' | 'resources' | 'glossary' | 'language' | 'display' | 'credits' | 'previous' | 'next' | 'exit';
  /**
   * false: the item stays in the list (and its options) but is not shown. The spacer is always on.
   * @default true
   */
  enabled?: boolean;
  /** The options of the item (see allOf below): logo { asset, alt, plate }, outline { screenTitle }, controls { seekBar, captionsByDefault, volume, transcript, speeds }, glossary { linkTerms }. */
  options?: { [key: string]: unknown };
};

export type PlayerLogoOptions = {
  /** The logo, relative to assets/ (SVG, PNG, WebP or JPEG; any size): the player scales it to the height of the bar. */
  asset?: AssetPath;
  /** What the logo says (an organisation's name). Leave it out when the title next to it says it: the logo is then decorative. */
  alt?: string;
  /**
   * The logo on a light plate: for a dark logo on a dark bar (W_PLAYER_LOGO_CONTRAST says when an SVG logo would not read on its bar).
   * @default false
   */
  plate?: boolean;
};

export type PlayerOutlineOptions = {
  /**
   * The button reads the title of the screen shown instead of « Sommaire ».
   * @default false
   */
  screenTitle?: boolean;
};

export type PlayerControlsOptions = {
  /**
   * Show the seek bar (how far it goes: course narration.seek). false: Play, Pause, Replay, the time and the step in words.
   * @default true
   */
  seekBar?: boolean;
  /**
   * Captions are on when a learner first comes (each learner's own choice is kept afterwards).
   * @default false
   */
  captionsByDefault?: boolean;
  /**
   * Show the volume (mute, and a slider).
   * @default true
   */
  volume?: boolean;
  /**
   * Show the transcript button (the script of the screen, by step, with its speakers).
   * @default true
   */
  transcript?: boolean;
  /**
   * The playback speeds learners may choose: none (1× only), 0.75× to 1.5×, or 0.75× to 2× (recommended: learners who go at their own pace stay).
   * @default '0.75-2'
   */
  speeds?: 'none' | '0.75-1.5' | '0.75-2';
};

export type PlayerGlossaryOptions = {
  /**
   * « Relier les termes aux écrans »: Elabora links each term or variant the first time it is in each screen (glossary:<id> links in the texts) when the option is turned on, when a term is added and on demand (elabora player --link-terms), never on its own afterwards: a link the author removed stays removed.
   * @default true
   */
  linkTerms?: boolean;
};

export type PlayerNoOptions = {};

export type Speaker = {
  /** Named by narration lines (speaker). */
  id: Slug;
  /** The name learners read in captions and in the transcript (Leïla, Narrator). */
  name: string;
  /** The voice that speaks each language, keyed by language tag (fr, en, fr-CA): the voice tools generate the lines of this speaker with it, and a generated line made with another voice is out of date. */
  voices?: { [key: string]: SpeakerVoice };
};

export type SpeakerVoice = {
  /** The voice tool that makes it (a local model, a voice service). */
  provider: string;
  /** The provider's id of the voice. */
  voice: string;
  /** The voice's name as its provider gives it, for a voice service whose voices Elabora does not list itself (ElevenLabs): shown to authors without asking the service. Information only: never makes a line out of date. */
  name?: string;
  /** What the provider needs besides the voice (speed, style…), as it defines it. ElevenLabs: model (eleven_v4 by default), stability and similarity (0 to 1). */
  settings?: { [key: string]: unknown };
};

/** A course variable. Strings need maxLength so the suspend data budget can be computed. */
export type Variable = {
  id: VariableId;
  type: 'boolean' | 'number' | 'string' | 'choice';
  /** Initial value; must match the type. */
  default: boolean | number | string;
  description?: string;
  /** Required for string variables. */
  maxLength?: number;
  /** Allowed values of a choice variable. */
  options?: string[];
  minimum?: number;
  maximum?: number;
  /**
   * Save in suspend data so the value survives a relaunch.
   * @default true
   */
  persist?: boolean;
};

/** Visual identity. tokens: the client charter (checked for contrast). custom: extra named values (colours, sizes) exposed as CSS variables and to free objects. stylesheet: free CSS for the whole course (cascade layer elabora.theme; its top-level @layer overrides blocks: elabora.overrides). cascade: where the theme sits among the cascade layers. fonts: embedded font files. styles: named styles that authors can pick per block or screen. Text never lives here: it stays in blocks. */
export type Theme = {
  /** Order of the cascade layers (docs/decisions.md D32). components-over-theme (what elabora init writes): the player, the theme's rules (the course's defaults), the component stylesheets, then the theme's top-level @layer overrides { … } blocks (what it overrides in components on purpose). theme-over-components: the order before 13 October 2026, the theme after the components, which it overrides whatever the specificity; what a course without cascade gets, so that it keeps its look. elabora theme upgrade moves a course from the second to the first without changing its look. */
  cascade?: 'components-over-theme' | 'theme-over-components';
  tokens?: {
    /** Main brand colour: buttons, progress, headings accents. */
    'color.primary'?: Color;
    /** Text on primary (contrast ≥ 4.5:1 with color.primary). */
    'color.onPrimary'?: Color;
    /** Secondary highlight colour. */
    'color.accent'?: Color;
    /** Page background. */
    'color.surface'?: Color;
    /** Body text (contrast ≥ 4.5:1 with color.surface). */
    'color.text'?: Color;
    /** Secondary text (contrast ≥ 4.5:1 with color.surface). */
    'color.muted'?: Color;
    /** Correct feedback (contrast ≥ 4.5:1 with color.surface). */
    'color.success'?: Color;
    /** Incorrect feedback (contrast ≥ 4.5:1 with color.surface). */
    'color.error'?: Color;
    /** Keyboard focus ring (contrast ≥ 3:1 with color.surface). */
    'color.focus'?: Color;
    /** CSS font stack for text. Only system or embedded fonts: no external font URL. */
    'font.body'?: string;
    'font.heading'?: string;
    /** Corner radius in px. */
    radius?: number;
    /** The player's top bar (D58). Default: color.primary. */
    'player.top.background'?: Color;
    /** Text and icons of the top bar (contrast ≥ 4.5:1 with player.top.background). Default: color.onPrimary. */
    'player.top.text'?: Color;
    /** The player's bottom bar. Default: color.surface. */
    'player.bottom.background'?: Color;
    /** Text and icons of the bottom bar (contrast ≥ 4.5:1 with player.bottom.background). Default: color.primary when it has that contrast with color.surface, else color.text. */
    'player.bottom.text'?: Color;
    /** Filled controls of the player: Next, Play, the seek bar, toggles turned on (contrast ≥ 3:1 with player.bottom.background). Default: color.primary. */
    'player.accent'?: Color;
    /** Text and icons on player.accent (contrast ≥ 4.5:1). Default: color.onPrimary. */
    'player.onAccent'?: Color;
    /** The filled part of the progress bar (contrast ≥ 3:1 with the bar it is in). Default: the text colour of that bar. */
    'player.progress'?: Color;
    /** The player's tooltips: refusals, hints, the seek bar's quote, glossary definitions. Default: color.text. */
    'player.tooltip.background'?: Color;
    /** Text of the tooltips (contrast ≥ 4.5:1 with player.tooltip.background). Default: color.surface. */
    'player.tooltip.text'?: Color;
    /** Corner radius of the player's buttons and panels in px; 999 (default) makes pills, as Lin draws them. */
    'player.radius'?: number;
    /** Size of the bars: comfortable (default: 56 and 72 px high at the reference window, 44 px buttons) or compact (48 and 60 px, for screens that need the room). */
    'player.density'?: 'comfortable' | 'compact';
  };
  /** Extra design tokens, for example {"color.blueprint": "#0F2A47", "space.section": "72px"}. Each becomes the CSS variable --t-<name with dots as hyphens> (--t-color-blueprint) in the player and in free objects, and can be bound to free-object props with x-token. Editors show them next to the charter tokens. */
  custom?: { [key: string]: string | number };
  /** Free CSS for the course, in theme/ (cascade layer elabora.theme, after the player and the components). Style the documented DOM contract (docs/design.md): data-screen, data-layout, data-type, data-component, data-style, .t-* classes, --t-* variables. url() must point to files inside the course (theme/ for fonts and textures, assets/ for generated images); no @import, no external URL. Use var(--t-…) for colours so a charter change propagates. */
  stylesheet?: string;
  /** Embedded fonts (WOFF2 or WOFF files in theme/). The player declares them with @font-face and passes them to free objects; reference the family in font.body / font.heading or in the stylesheet. Check the font licence allows embedding (OFL fonts do). A face split into subset files (latin, latin-ext) is one entry per file, each with its unicodeRange. */
  fonts?: ThemeFont[];
  /** Named styles declared by the theme, per type (a built-in type, a course component id, or "screen"), with a one-line description for editors: {"callout": {"rule": "Key rule on a dark card"}}. Blocks and screens pick one with style; the player adds data-style and the class t-s-<name>; the stylesheet styles it. Styles declared for a type also apply to its forks. Components can declare their own styles in component.json. (Not to be confused with the callout prop variant: info, tip, warning, important.) */
  styles?: { [key: string]: { [key: string]: string } };
  /** Effects of the theme for timed blocks (block timing.in and timing.out effect), each with a one-line description for editors: {"pop": "Grows a little past its size, then settles"}. The stylesheet defines @keyframes t-fx-<name> (how the block comes) and may define @keyframes t-fx-<name>-out (how it goes; default: the first one played backwards). The player plays them at the timeline's time, as the built-in effects (none, fade, rise, slide, zoom, wipe, draw, whose names are taken). Keep them relative to the block (transform, opacity, clip-path, filter): never move the layout, never flash (WCAG 2.3.1). */
  effects?: { [key: string]: string };
  /** Decorative background behind every screen. Decoration only: it carries no information, takes no focus and is hidden from screen readers (a scene that teaches is a free-object block). layers: empty elements behind the course that the stylesheet paints and animates (.t-backdrop-layer[data-layer="far"]); the backdrop element carries data-screen, data-section, data-step and data-variant, so the stylesheet can react to where the learner is. object: a decorative free object (pedagogicalRole "decoration") mounted once behind the course for the whole session, given the same context. Under reduced motion CSS animations stop and the object shows still frames; on a slow machine the object freezes. Text over a backdrop must stay readable: elabora fit measures its contrast against the pixels behind it (W_TEXT_CONTRAST_MEASURED). */
  backdrop?: {
    /** Layer names, back to front: <div class="t-backdrop-layer" data-layer="<name>"> each. */
    layers?: string[];
    /** Decorative free object of objects/<id>/ (pedagogicalRole decoration) and its prop values. */
    object?: {
      id: string;
      /** Prop values, checked against the manifest. */
      props?: { [key: string]: unknown };
    };
    /** Named variants a screen can pick with backdrop, each with a one-line description for editors: {"dim": "Darker sky behind dense screens"}. The stylesheet styles .t-backdrop[data-variant=…]; the object receives the variant. */
    variants?: { [key: string]: string };
  };
};

export type ThemeFont = {
  family: string;
  src: string;
  /**
   * Weight or weight range of a variable font, for example "100 900".
   * @default '400'
   */
  weight?: string;
  /** @default 'normal' */
  style?: 'normal' | 'italic';
  /** The characters the file holds, as a CSS unicode-range, for example "U+0100-02BA,U+1E00-1E9F" (the latin-ext subset of a font): the browser downloads the file only for pages that use one of them. Default: every character. */
  unicodeRange?: string;
};

// plan.schema.json

/**
 * Elabora plan (plan.json)
 *
 * The contract layer: the plan the client validates (objectives, ordered plan items, locked texts, assessment questions, sources). plan.json is always the working copy, written directly by the author and their agent at any time; its versions (V1, V2…: frozen copies made by hand, sent to the client, one of them validated) are in plan-versions/ (D52). Release builds need a validated version.
 */
export type Plan = {
  $schema?: string;
  /** Plan identifier, for example PLAN-ACME-NET-V3. */
  id: PlanId;
  title: string;
  /** Business outcome the course serves (guardrail A4). */
  businessGoal?: string;
  audience?: {
    role?: string;
    priorKnowledge?: 'low' | 'medium' | 'high';
    notes?: string;
  };
  /** The learner time the course is meant to take, in minutes, as the author or the client asked for it: a range (min and max, min not above max), one figure (min equal to max), a floor (min alone: longer than that, where an agent proposes several modules) or a ceiling (max alone). course.json durationMinutes is the time of the built course, written into the package. */
  duration?: {
    min?: number;
    max?: number;
  };
  /** Before the plan is validated: what the agent decided by itself because the author left it open (a 3D scene, the tone, the format), which the author reads first in the app's Plan view and may change. Written in the course language, a few words each. Validating a version of the plan removes it, and it is outside the content hash: no version holds it, it is never part of the contract (D51). */
  decided?: PlanDecision[];
  /** Before the plan is validated: the one question the agent asks the author now, the one whose answer would change the plan most; the next comes once it is answered. The plan is written whole meanwhile. Validating a version of the plan removes it, and it is outside the content hash (D51). */
  question?: {
    /** The question, in the course language, that the author can answer in a sentence. */
    text: string;
    topic?: PlanTopic;
    /** The plan items the answer would change. */
    items?: PlanId[];
  };
  /** Sources of truth provided by the client or experts. Factual claims should cite them (guardrail G1). */
  sources?: PlanSource[];
  objectives: PlanObjective[];
  /** Ordered storyboard items. Every item must be covered by at least one screen (guardrail A1), and every screen must cover at least one item. */
  items: PlanItem[];
  /** Planned spaced retrieval after the module (guardrail B5), for example ["D+2", "D+7", "D+30"]. Delivered outside the package (LMS reminders, emails, micro-modules). */
  spacing?: string[];
  /** Approved exceptions to pedagogical warnings. They are listed in the proof report. */
  waivers?: PlanWaiver[];
  /** Set by elabora translate build: the source plan this one translates (its id, content hash and language). The translated plan needs its own approval (elabora translate approve), which the translated course holds as its validated version. */
  translationOf?: {
    id: string;
    contentHash: string;
    language: string;
  };
};

export type PlanDecision = {
  /** What was decided. The app names these topics as its « Nouveau module » page asks them: audience, duration, language, format, 3d, voices, business-goal, quizzes, case, tone, brand, accessibility, lms. Another topic needs a label. */
  topic: PlanTopic;
  /** The question as the author would ask it, for a topic the app does not name (« Un fil rouge ? »). */
  label?: string;
  /** What the agent chose (« Oui : le réseau du site, à explorer »). */
  choice: string;
  /** Where it shows or why, in a few words (« partie 3, comme le demande le brief »). */
  why?: string;
  /** The plan items the decision shapes. */
  items?: PlanId[];
};

export type PlanSource = {
  id: PlanId;
  title: string;
  /** For example internal procedure, regulation, expert interview. */
  type?: string;
  version?: string;
};

export type PlanObjective = {
  id: PlanId;
  /** Observable behaviour: action verb, condition, criterion (guardrail A3). Avoid 'understand' or 'know' alone. */
  statement: string;
  /** A short name of three to five words (« Les contrefaçons »), shown beside the objective's number wherever the plan refers to it. Optional: without it, the start of the statement. */
  short?: string;
  bloom?: 'remember' | 'understand' | 'apply' | 'analyze' | 'evaluate' | 'create';
  /** Success criterion, for example 4 out of 5 scenarios solved. */
  criterion?: string;
  sources?: PlanId[];
};

export type PlanWaiver = {
  /** Diagnostic code waived. */
  code: string;
  /** Optional id the waiver is limited to (screen, block, item). */
  target?: string;
  reason: string;
  approvedBy: string;
};

/** A choice the author makes or leaves to the agent: lowercase letters, digits and hyphens. */
export type PlanTopic = string;

export type PlanItem = {
  id: PlanId;
  /** Pedagogical function. practice, scenario and assessment items need learner activity (retrieval, decision or production). */
  kind: 'intro' | 'exposition' | 'demonstration' | 'practice' | 'scenario' | 'assessment' | 'summary';
  title: string;
  /** The part of the module the item belongs to, by its title (« Le texte du Gai Savoir »): consecutive items with the same part make one part, an item without one continues the part before it, and the course's sections follow them. Optional: a plan without parts takes those of course.json, the sections that hold its items' screens. */
  part?: string;
  /** What the validated storyboard says this item contains. */
  description?: string;
  /** The voice-over the client validated for this item (a storyboard's voice-over column), line by line: a screen that covers the item takes it as its narration script (elabora narration from-plan, the app's « Reprendre la voix off du plan »). */
  voiceover?: PlanItemVoiceover[];
  /** Objectives served. May be empty only for intro and summary items. */
  objectives: PlanId[];
  sources?: PlanId[];
  /** Validated texts. Blocks reuse them with textRef, so the module always shows the plan's wording: rewording one on the canvas writes it here. */
  lockedTexts?: LockedText[];
  /** Validated questions. Quiz blocks reuse them with questionRef. */
  questions?: PlanQuestion[];
};

export type PlanItemVoiceover = {
  /** A speaker of course.json speakers (default: the first). */
  speaker?: Slug;
  /** Word for word what is said. */
  text: string;
};

export type LockedText = {
  id: PlanId;
  text: Markdown;
  /** The client wants this text as signed, « à l'identique » (a legal notice, a quote): only the author changes it, deliberately; agents' writes that change it are refused, and a change since the validated version is flagged (W_PLAN_VERBATIM_CHANGED). */
  verbatim?: boolean;
};

export type PlanQuestion = {
  id: PlanId;
  stem: Markdown;
  /** single / multiple: choice question with options. numeric: the learner types a number (answer, tolerance, unit, feedback, misconceptions). */
  mode: 'single' | 'multiple' | 'numeric';
  objectives?: PlanId[];
  bloom?: 'remember' | 'understand' | 'apply' | 'analyze' | 'evaluate' | 'create';
  options?: PlanQuestionOption[];
  answer?: number;
  tolerance?: NumericTolerance;
  unit?: string;
  feedback?: NumericFeedback;
  misconceptions?: Misconceptions;
};

export type PlanQuestionOption = {
  id: string;
  text: string;
  correct: boolean;
  /** Elaborated feedback: why this option is right or wrong (guardrail D1). */
  feedback?: Markdown;
};

// plan-version.schema.json

/**
 * A version of the plan (plan-versions/V<n>.json)
 *
 * A frozen copy of plan.json, made by hand (elabora plan version, the app's « Créer la V3 »), never by an agent nor by an export (D52). Its number, day, plan and content hash never change; its sends and its validation are added when they happen. The notes for the client explain its changes since the version before it. Kept with the course (its history, its .elabora archives), never in a SCORM or web package.
 */
export type PlanVersion = {
  $schema?: string;
  /** Its number: V1 is 1. The file is named after it (plan-versions/V1.json). */
  version: number;
  /** The day it was made, in the author's time zone. */
  date: CalendarDate;
  /** What the author said of it when making it (« Après la réunion du 3 octobre »). */
  note?: string;
  /** SHA-256 of the canonical plan below, without $schema and what the agent decided and asks while it was a draft (planContentHash). */
  contentHash: string;
  /** plan.json as it was when the version was made. */
  plan: Plan;
  /** Notes for the client, one per change since the version before, frozen with the version: the document shows them in its margin and Word as comments. */
  notes?: PlanNote[];
  /** Each time the version was exported for the client: the day and the format. Exporting adds one; it never makes a version. */
  sends?: PlanSend[];
  /** The client validated this version (elabora plan approve, the app's « Valider… »), never an agent. */
  validation?: {
    /** Who validated (name and organisation). */
    by: string;
    date: CalendarDate;
    /** Where the validation is written (an email, minutes, a purchase order). */
    reference?: string;
  };
};

export type PlanSend = {
  date: CalendarDate;
  format: 'docx' | 'pdf' | 'html' | 'review';
};

export type PlanNote = {
  /** The change it explains, by its key in the plan's diff: item:ITEM-3, text:TXT-2, plan:businessGoal… */
  target: string;
  /** The note, in the course language, as the client reads it. */
  text: string;
};

// plan-notes.schema.json

/**
 * Notes for the client on changes not in a version yet (plan-versions/notes.json)
 *
 * The author's notes for the client on the changes made since the latest version of the plan, one per change, optional (D52). The next version takes those whose change is still there and freezes them; the document of the working copy shows them in its margin and Word as comments. Never in a SCORM or web package.
 */
export type PlanNotes = {
  $schema?: string;
  notes: PlanNote[];
};

// screen.schema.json

/**
 * Elabora screen (screens/<id>.json)
 *
 * One screen of the course: blocks in reading order, optional layers (overlays opened by events, like Storyline layers) and events. Each screen covers at least one plan item.
 */
export type Screen = {
  $schema?: string;
  /** Must match the file name screens/<id>.json. */
  id: Slug;
  /** Screen title, rendered as the level-1 heading and used in the menu. */
  title: string;
  /** Plan items this screen implements. No screen without a plan item (guardrail A1). */
  covers: PlanId[];
  /** Layout of the screen: the id of a screen-level component (components/<id>/, level "screen"), an HTML/CSS template with named slots. Blocks choose their slot with slot; blocks without slot go to the default slot. Without layout, blocks stack in one column. */
  layout?: Slug;
  /** Values of the props declared by the layout component (a kicker, a background token…). Text and Markdown props may be { "textRef": "TXT-n" }. */
  layoutProps?: { [key: string]: unknown };
  /** Named screen style declared in course.json theme.styles.screen. */
  style?: string;
  /** Backdrop of this screen: a variant declared in theme.backdrop.variants, or none (no backdrop: the object pauses). Default: the course backdrop as it is. */
  backdrop?: string;
  /**
   * Counts for course completion.
   * @default true
   */
  required?: boolean;
  /**
   * viewed: complete as soon as it is shown. interactions-done: when every quiz and decision is answered and every free object has emitted its completion event. action: only when an event runs complete-screen.
   * @default 'viewed'
   */
  completeWhen?: 'viewed' | 'interactions-done' | 'action';
  /**
   * Whether Continue reveals the next step (the Continue button in the page in scroll presentation, the Next button in slides). false: only the screen's own triggers reveal its steps (click events with reveal-step on markers or buttons, like the builds of a Storyline slide, or steps that open once answered); the button reads Next and, with navigation.lockUntilComplete, waits for the last step.
   * @default true
   */
  continueRevealsSteps?: boolean;
  /** How each step of the screen opens, keyed by step number (blocks carry the step). By default a step opens with Continue: in scroll presentation a Continue button in the page, at the cut, like the continue dividers of Rise; in slides the Next button, relabelled Continue. opens "answered": the step opens by itself once every activity of the steps above is answered (submitted, right or wrong), like content shown after a knowledge check. */
  steps?: { [key: string]: ScreenStep };
  /** The voice of the screen, script first: its lines in the order they are spoken, each in a step of the screen. A narrated screen has a timeline: its steps are segments of the narration, the player shows a bar (play, pause, replay the step, seek, captions, speed, transcript) and captions and the transcript are generated from the lines. The audio of each line lives in assets/narration/<language>/<screen>/<line>.m4a with its sidecar <line>.json (docs/decisions.md D24); the build lays the lines of a screen end to end into one track. */
  narration?: {
    /** learner (default, or the course's narration.advance): playback stops at the end of each step and Continue plays the next one. auto: the steps follow each other; the learner can always pause. next-screen: the steps follow each other, then the player goes to the next screen by itself (an introduction, credits: a time limit learners did not choose, WCAG 2.2.1, W_AUTO_ADVANCE). Learners may turn auto and next-screen back into learner with « M'arrêter à chaque étape »; phones always go step by step. */
    advance?: 'learner' | 'auto' | 'next-screen';
    /** How far the learner may move in the timeline (default: the course's narration.seek, else seen). seen: back anywhere, forward up to the furthest point reached. free: anywhere. none: no seek bar, play, pause and replay the step only. */
    seek?: 'seen' | 'free' | 'none';
    lines: ScreenNarrationLine[];
  };
  blocks: Block[];
  layers?: ScreenLayer[];
  events?: Event[];
  /**
   * Render the title visibly (it stays available to screen readers when false).
   * @default true
   */
  showTitle?: boolean;
};

export type ScreenStep = {
  /**
   * continue: the learner presses Continue (in the page in scroll presentation, Next in slides). answered: it opens by itself once the activities of the steps above are answered.
   * @default 'continue'
   */
  opens?: 'continue' | 'answered';
  /** Text of the Continue button that opens this step in scroll presentation (default: the player's Continue label). */
  label?: string;
  /** Screens without narration whose blocks are timed in seconds: how long this step's stretch of the timeline lasts (default: until its last timed block has come or gone). A narrated step lasts as long as its lines. */
  duration?: number;
};

export type ScreenNarrationLine = {
  /** Unique in the screen (l1, l2…): cues, translations and the line's audio files are named by it. */
  id: Slug;
  /** A speaker of course.json speakers, named in the captions and the transcript. Default: the first speaker of the course (none: no name). */
  speaker?: Slug;
  /** What the voice says, word for word: the captions and the transcript. Do not show the same words on screen (E4, W_NARRATION_DUPLICATED). Words in square brackets are stage directions for an expressive voice ([chuchote], [rit], [un temps]: how to say it, where the delivery changes): never shown nor counted as words; a voice that cannot play them says the line without them. */
  text: string;
  /**
   * The step of the screen this line belongs to: its segment of the timeline. Lines are in step order.
   * @default 1
   */
  step?: number;
  /** Seconds of silence before the line. Default: 0.4, and 0 for the first line of the screen. */
  pauseBefore?: number;
  /** How a generated voice says this line, by language (it is translated): settings of the voice tool (speed, style…) over those of the speaker's voice in that language, for example { "fr": { "speed": 1.1 } }. Other settings make the line's audio out of date. */
  delivery?: { [key: string]: { [key: string]: unknown } };
  /** How a generated voice says words of this line, by language, before those of the course. */
  pronunciations?: Pronunciations;
};

export type ScreenLayer = {
  id: Slug;
  /** Accessible title of the layer dialog. */
  title: string;
  /**
   * dialog: modal window over the dimmed course; the learner closes it to go on. panel: opens over part of the screen, which stays usable (like a Storyline layer); for feedback, hints and details that must not move the slide.
   * @default 'dialog'
   */
  presentation?: 'dialog' | 'panel';
  blocks: Block[];
};

// block.schema.json

/** A block placed on a screen, a layer or in a slot of a component instance. id identifies it in the whole course. type is a built-in type (the native catalogue, props in blocks/<type>.schema.json) or the id of a course component (components/<id>/component.json declares its props). */
export type Block = {
  id: Slug;
  /** Built-in type (heading, text, image, video, audio, callout, button, accordion, math, quiz, numeric, decision, free-object, results, stack; charts: key-figures, bars, donut, trend, proportion, before-after, levels, process, cycle, matrix, milestones, diagram) or the id of a course component. Call elabora_list_components (MCP) for the types of this course and elabora_get_schema for their props. */
  type: string;
  props: { [key: string]: unknown };
  /** Blocks placed in the slots of this component instance (each picks its slot with slot; without slot, the default slot). Only for components that declare slots. */
  blocks?: Block[];
  /**
   * Initial state: hidden blocks are shown later by a show-block action.
   * @default false
   */
  hidden?: boolean;
  /**
   * Step of the screen that reveals this block (blocks of the screen, not those nested in a component or in a layer). Next, labelled Continue while steps remain, reveals the following step before leaving the screen: below the previous ones in scroll presentation, in their reserved place in slides. Activities of a step must be done before Continue when navigation.lockUntilComplete is set. A screen visited before shows all its steps.
   * @default 1
   */
  step?: number;
  /** When the block appears (in) and leaves (out) on the screen's timeline, and how: anchored to the narration's lines and words ("in": { "at": { "line": "l2", "word": "imprimante" }, "effect": "rise" }), or in seconds on a screen without narration. Without in, it shows from the start of its step; without out, until the end of the screen. A timed block keeps its place while it is not there (nothing moves around it), stays out of reach of the keyboard and of screen readers until it shows, and is recomputed when learners seek: what is seen is a function of the time. Blocks of the screen and of its components' slots (the contents of a stack follow one another); not in layers. */
  timing?: {
    in?: Moment;
    out?: Moment;
  };
  /**
   * Layout hint in the default column layout. Two consecutive half blocks sit side by side on wide screens and stack on small ones. Inside a layout slot, the layout CSS decides.
   * @default 'full'
   */
  width?: 'full' | 'wide' | 'half';
  /** Slot that receives this block: a slot of the screen layout for blocks of the screen, a slot of the component instance for blocks inside its blocks. Reading order follows the template, then the block order. */
  slot?: Slug;
  /** Named style declared for this type: in course.json theme.styles.<type> or in the component's styles (also those of its parents). */
  style?: string;
  /** Note for reviewers and authors; never shown to learners. */
  note?: string;
};

/** A built-in value of Block.type. */
export type BuiltinBlockType =
  | 'heading'
  | 'text'
  | 'image'
  | 'video'
  | 'audio'
  | 'callout'
  | 'button'
  | 'accordion'
  | 'math'
  | 'quiz'
  | 'numeric'
  | 'decision'
  | 'free-object'
  | 'results'
  | 'stack'
  | 'key-figures'
  | 'bars'
  | 'donut'
  | 'trend'
  | 'proportion'
  | 'before-after'
  | 'levels'
  | 'process'
  | 'cycle'
  | 'matrix'
  | 'milestones'
  | 'diagram';

/** A Block whose type is built in: its props follow the schema of that type. */
export type BuiltinBlock =
  | HeadingBlock
  | TextBlock
  | ImageBlock
  | VideoBlock
  | AudioBlock
  | CalloutBlock
  | ButtonBlock
  | AccordionBlock
  | MathBlock
  | QuizBlock
  | NumericBlock
  | DecisionBlock
  | FreeObjectBlock
  | ResultsBlock
  | StackBlock
  | KeyFiguresBlock
  | BarsBlock
  | DonutBlock
  | TrendBlock
  | ProportionBlock
  | BeforeAfterBlock
  | LevelsBlock
  | ProcessBlock
  | CycleBlock
  | MatrixBlock
  | MilestonesBlock
  | DiagramBlock;

export type HeadingBlock = Omit<Block, 'type' | 'props'> & {
  type: 'heading';
  props: HeadingProps;
};

export type TextBlock = Omit<Block, 'type' | 'props'> & {
  type: 'text';
  props: TextProps;
};

export type ImageBlock = Omit<Block, 'type' | 'props'> & {
  type: 'image';
  props: ImageProps;
};

export type VideoBlock = Omit<Block, 'type' | 'props'> & {
  type: 'video';
  props: VideoProps;
};

export type AudioBlock = Omit<Block, 'type' | 'props'> & {
  type: 'audio';
  props: AudioProps;
};

export type CalloutBlock = Omit<Block, 'type' | 'props'> & {
  type: 'callout';
  props: CalloutProps;
};

export type ButtonBlock = Omit<Block, 'type' | 'props'> & {
  type: 'button';
  props: ButtonProps;
};

export type AccordionBlock = Omit<Block, 'type' | 'props'> & {
  type: 'accordion';
  props: AccordionProps;
};

export type MathBlock = Omit<Block, 'type' | 'props'> & {
  type: 'math';
  props: MathProps;
};

export type QuizBlock = Omit<Block, 'type' | 'props'> & {
  type: 'quiz';
  props: QuizProps;
};

export type NumericBlock = Omit<Block, 'type' | 'props'> & {
  type: 'numeric';
  props: NumericProps;
};

export type DecisionBlock = Omit<Block, 'type' | 'props'> & {
  type: 'decision';
  props: DecisionProps;
};

export type FreeObjectBlock = Omit<Block, 'type' | 'props'> & {
  type: 'free-object';
  props: FreeObjectProps;
};

