// blocks/free-object.schema.json

/**
 * free-object block props
 *
 * Places a free object (governed custom code, for example a three.js scene) on the screen. The object lives in objects/<object>/ with its manifest, code, tests and notes. props holds values for the props the manifest declares: change them here, never in the code.
 */
export type FreeObjectProps = {
  /** Free object id (folder name in objects/). */
  object: Slug;
  /** Accessible name of the embedded object. */
  title: string;
  /** Values of the props declared in the object manifest. Missing props use their manifest default. */
  props?: { [key: string]: unknown };
  /** What screen readers say about the object, worded for this block (defaults: the manifest a11y description and keyboard). Translations write here. */
  a11y?: {
    description?: string;
    keyboard?: string;
  };
  /** Wording of the object's strings for this block (keys declared in the manifest strings; same placeholders). Required when the course language differs from the manifest language; translations write here. */
  strings?: { [key: string]: string };
  /** Wording of the values of the object's choices for this block, as the editor shows them (defaults: the manifest x-enum-labels). Keys are props with an enum, or <prop>.<field> for a field of a list's items; each maps values of that enum to words. Translations write here. */
  enumLabels?: { [key: string]: { [key: string]: string } };
  /**
   * Shape of the frame on wide containers. auto: the object sets its height with host.requestHeight(px). fill: the frame takes the height of its layout slot.
   * @default '16:9'
   */
  aspectRatio?: AspectRatio;
  /** Shape when the block is narrower than 640 px (phones, narrow slots). Typically 3:4, 2:3 or auto. Defaults to aspectRatio. */
  narrowAspectRatio?: AspectRatio;
  /** Minimum frame height in px. */
  minHeight?: number;
  /** Maximum frame height in px. */
  maxHeight?: number;
  /** Equivalent text activity or full description, shown on demand (WCAG 1.1.1). */
  textAlternative: Markdown;
  /**
   * Use the object's score event in the course score.
   * @default false
   */
  scored?: boolean;
  /** @default 1 */
  weight?: number;
};

// blocks/heading.schema.json

/**
 * heading block props
 *
 * A section heading inside a screen. The screen title is already rendered as the level-1 heading.
 */
export type HeadingProps = {
  /** Heading text. Use text or textRef, not both. */
  text?: string;
  /** Id of a validated text of the plan: the block shows the plan's wording, and rewording it writes the plan. */
  textRef?: PlanId;
  /**
   * Heading level. Do not skip levels.
   * @default 2
   */
  level?: 2 | 3 | 4;
};

// blocks/image.schema.json

/**
 * image block props
 *
 * An image from the assets folder.
 */
export type ImageProps = {
  asset: AssetPath;
  /** Text alternative. Required unless decorative is true. */
  alt?: string;
  /**
   * True only if the image carries no information.
   * @default false
   */
  decorative?: boolean;
  caption?: string;
  /**
   * True if produced by an AI model; the player shows a mark and the build report lists it.
   * @default false
   */
  generated?: boolean;
  /**
   * SVG only: the drawing goes into the page instead of an <img>, so that the draw effect of a timing traces its strokes and the theme's CSS and currentColor reach its shapes. Sanitized when it is built: no script, no event handler, no link or reference out of the drawing; its ids prefixed with the block's, its own <style> scoped to it. Named by alt (role img), or hidden when decorative. Keep it for figures that need it: an inline drawing is part of the page's weight.
   * @default false
   */
  inline?: boolean;
};

